#!/usr/bin/env python3
"""A compiled DXIL shader, as the Direct3D 12 runtime hands it to a driver.

The Direct3D 12 runtime gives a user-mode driver a shader's program and its
signatures as registers, masks and system values (D3D12DDIARG_CREATE_SHADER),
not the container the application compiled. This splits a dxc container that
way - the DXIL chunk's program, and each signature as the executor's wire
carries it, set to the stage's - and writes both, with the container itself
for the path that takes one whole, as a C++ header:

    ddi_dxil_fixture.py <name> <stage> <shader.dxil> > <name>.hpp

stage is the wire's: 0 vertex, 1 hull, 2 domain, 3 geometry, 4 pixel. The
system values are the token format's (D3D10_SB_NAME); a pixel shader's
render-target outputs carry none.
"""
import struct
import sys

TARGET = 64
DEPTH = 65


def chunks(blob):
    assert blob[:4] == b"DXBC", "not a container"
    count = struct.unpack_from("<I", blob, 28)[0]
    for offset in struct.unpack_from(f"<{count}I", blob, 32):
        size = struct.unpack_from("<I", blob, offset + 4)[0]
        yield blob[offset:offset + 4].decode(), blob[offset + 8:offset + 8 + size]


def signature(data, set_):
    count = struct.unpack_from("<I", data, 0)[0]
    entries = []
    for index in range(count):
        stream, _name, _index, sv, component, register, mask, _rw = struct.unpack_from("<IIIIIIBB", data,
                                                                                       8 + index * 32)
        precision = struct.unpack_from("<I", data, 8 + index * 32 + 28)[0]
        if sv in (TARGET, DEPTH):
            sv = 0
        entries.append((set_, sv, register, mask, component, precision, stream, 0))
    return entries


def words(name, data):
    padded = data + b"\0" * (-len(data) % 4)
    values = struct.unpack(f"<{len(padded) // 4}I", padded)
    print(f"inline constexpr std::uint32_t {name}[] = {{")
    for row in range(0, len(values), 8):
        print("    " + ", ".join(f"0x{v:08x}u" for v in values[row:row + 8]) + ",")
    print("};")
    print(f"inline constexpr std::uint64_t {name}_bytes = {len(data)}u;\n")


def main():
    name, stage, path = sys.argv[1], int(sys.argv[2]), sys.argv[3]
    blob = open(path, "rb").read()
    program, entries = b"", []
    for tag, data in chunks(blob):
        if tag == "DXIL":
            program = data
        elif tag == "ISG1":
            entries += signature(data, stage * 3)
        elif tag == "OSG1":
            entries += signature(data, stage * 3 + 1)
    print(f"/* {name}: generated by tests/fixtures/d3d12/ddi_dxil_fixture.py from {path.split('/')[-1]}. */")
    print("#pragma once\n\n#include \"proto/generated/d3d12/d3d12_wire_types.h\"\n\n#include <cstdint>\n")
    print(f"namespace {name} {{\n")
    words("program", program)
    words("container", blob)
    print("inline constexpr av::d3d12proto::SignatureEntry signatures[] = {")
    for entry in entries:
        print("    {" + ", ".join(f"{v}u" for v in entry) + "},")
    print("};")
    print(f"inline constexpr std::uint32_t signatures_count = {len(entries)}u;\n")
    print(f"}}  // namespace {name}")


if __name__ == "__main__":
    main()
